import {armSpread} from './garment-fit.js';
import {createDessertBase} from './dessert-bases.js';
import * as T from './vendor/three.module.js';
import {addClothing} from './clothing.js';
import {addProps} from './props.js';
import {sourceModel} from './source-base.js';
import {boneDefs} from './avatar.js';
import {addGlasses} from './glasses.js';
import {characterHead} from './head-sculpt.js';
import {facetMesh} from './surface.js';
import {mergedBody} from './merged-body.js';
import {addHeadset} from './headset.js';
import {groupAccessories} from './accessory-transforms.js';
import {addAnimalEars} from './animal-ears.js';
import {addTail} from './tails.js';
import {addExtras} from './extras.js';
import {addTufts} from './tufts.js';
import {addOutlines} from './outline.js';
const sourceToTarget=[0,1,2,3,4,5,5,5,7,8,11,12,14,15,16,17,18,19,2,2,20,21];
function geometryFor(key,s){const part=sourceModel.parts[key];let positions=[],uvs=[],indices=[],weights=[];const shift=(1.54/5.2)*(s.legs-1);for(let i=0;i<part.positions.length/3;i++){let x=part.positions[i*3]/5.2,y=part.positions[i*3+1]/5.2,z=part.positions[i*3+2]/5.2;if([3,8,10].includes(key))x*=s.body;if(key>=12&&key<=17)y*=s.legs;else y+=shift;if(key===6||key===7){const origin=sourceModel.bones[key].position.map(v=>v/5.2);x=origin[0]+(x-origin[0])*s.ears;y=origin[1]+shift+(y-origin[1]-shift)*s.ears;}positions.push(x,y,z);uvs.push(part.uvs[i*2],1-part.uvs[i*2+1]);for(let j=0;j<4;j++){indices.push(sourceToTarget[part.skinIndices[i*4+j]]??0);weights.push(part.skinWeights[i*4+j]);}}
 const levels=s.detail==='verylow'?0:s.detail==='low'?1:2;for(let level=0;level<levels;level++){const p2=[],u2=[],i2=[],w2=[];const vertex=i=>({p:positions.slice(i*3,i*3+3),uv:uvs.slice(i*2,i*2+2),bi:indices.slice(i*4,i*4+4),bw:weights.slice(i*4,i*4+4)});const middle=(a,b)=>{const map=new Map();a.bi.forEach((i,k)=>map.set(i,(map.get(i)||0)+a.bw[k]*.5));b.bi.forEach((i,k)=>map.set(i,(map.get(i)||0)+b.bw[k]*.5));const sorted=[...map].sort((a,b)=>b[1]-a[1]).slice(0,4);while(sorted.length<4)sorted.push([0,0]);return{p:a.p.map((x,k)=>(x+b.p[k])/2),uv:a.uv.map((x,k)=>(x+b.uv[k])/2),bi:sorted.map(x=>x[0]),bw:sorted.map(x=>x[1])};};const push=v=>{p2.push(...v.p);u2.push(...v.uv);i2.push(...v.bi);w2.push(...v.bw);};for(let i=0;i<positions.length/3;i+=3){const a=vertex(i),b=vertex(i+1),c=vertex(i+2),ab=middle(a,b),bc=middle(b,c),ca=middle(c,a);[a,ab,ca,ab,b,bc,ca,bc,c,ab,bc,ca].forEach(push);}positions=p2;uvs=u2;indices=i2;weights=w2;}
 const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(positions,3));geometry.setAttribute('uv',new T.Float32BufferAttribute(uvs,2));geometry.setAttribute('skinIndex',new T.Uint16BufferAttribute(indices,4));geometry.setAttribute('skinWeight',new T.Float32BufferAttribute(weights,4));geometry.computeVertexNormals();if(true){const normals=geometry.attributes.normal,groups=new Map();for(let i=0;i<positions.length/3;i++){const key=positions.slice(i*3,i*3+3).map(x=>x.toFixed(5)).join(',');if(!groups.has(key))groups.set(key,{indices:[],normal:new T.Vector3()});const group=groups.get(key);group.indices.push(i);group.normal.add(new T.Vector3().fromBufferAttribute(normals,i));}for(const group of groups.values()){group.normal.normalize();for(const i of group.indices)normals.setXYZ(i,...group.normal.toArray());}normals.needsUpdate=true;}return geometry;}
export function buildSourceAvatar(s){const root=new T.Group();root.name='PixelPals';root.userData.pixelPals={version:1,state:{...s}};const bones=boneDefs.map(([,name])=>{const b=new T.Bone();b.name=name;return b;});const shift=(1.54/5.2)*(s.legs-1);const sourcePositions=sourceModel.bones.map(b=>new T.Vector3(...b.position).divideScalar(5.2));const absolute=Array.from({length:22},()=>new T.Vector3());for(let i=0;i<22;i++){const source=sourceToTarget.indexOf(i);if(source>=0)absolute[i].copy(sourcePositions[source]);if(i>=14&&i<=21)absolute[i].y*=s.legs;else absolute[i].y+=shift;}for(const side of[1,-1]){const sh=side===1?6:10,arm=sh+1,elbow=sh+2,wrist=sh+3;absolute[sh].copy(absolute[arm]);absolute[wrist].copy(absolute[elbow]).add(new T.Vector3(side*.06,-.08,0));for(const i of[sh,arm,elbow,wrist])absolute[i].x*=s.body;}for(const i of[14,15,16,20])absolute[i].x=.147;for(const i of[17,18,19,21])absolute[i].x=-.147;for(const side of[1,-1]){const a=side===1?7:11;absolute[a-1].x=absolute[a].x=side*.16*s.body;absolute[a+1].x=side*(.255+armSpread(s)*.5)*s.body;absolute[a+2].x=side*(.323+armSpread(s))*s.body;}absolute[4].y+=.10;absolute[5].y+=.10;for(const i of[6,7,10,11])absolute[i].y+=.10;for(const i of[8,12])absolute[i].y+=.035;absolute[0].set(0,0,0);bones.forEach((bone,i)=>{const parent=boneDefs[i][2];bone.position.copy(absolute[i]).sub(parent<0?new T.Vector3():absolute[parent]);(parent<0?root:bones[parent]).add(bone);});bones[5].scale.setScalar(1);root.updateMatrixWorld(true);const skeleton=new T.Skeleton(bones);const fur=new T.MeshStandardMaterial({color:s.bodyColor,roughness:.95,flatShading:s.filter==='lowpoly'}),arm=s.armSeparate?new T.MeshStandardMaterial({color:s.armColor,roughness:.95}):fur;fur.userData.colorSetting='bodyColor';if(s.armSeparate)arm.userData.colorSetting='armColor';const materials=[fur,arm];let face;
 function addPart(key,material){const mesh=new T.SkinnedMesh(geometryFor(key,s),material);root.add(mesh);mesh.castShadow=true;mesh.receiveShadow=false;mesh.name=key===5?'SourceHead':'SourcePart'+key;mesh.bind(skeleton);if(key===5)face=mesh;return mesh;}
 const body=new T.SkinnedMesh(mergedBody(s,s.armSeparate),s.armSeparate?[fur,arm]:fur);body.name='SculptedBody';body.castShadow=true;root.add(body);body.bind(skeleton);
 const headOrigin=sourcePositions[5].toArray();const sculpt=characterHead(s.clothing==='hoodieUp'&&s.hoodEarMode!=='outside'&&['cat','fox','wolf'].includes(s.species)?{...s,species:'none'}:s,headOrigin,shift+.10);face=new T.SkinnedMesh(sculpt.geometry,sculpt.material);face.name='SculptedHead';face.castShadow=true;root.add(face);face.bind(skeleton);materials.push(sculpt.material);
 if(s.glasses)addGlasses(bones[5],s,{y:.07,z:.18});
 if(s.headset)addHeadset(bones[5],s,headOrigin,sculpt.surface);
 addAnimalEars(bones[5],s,headOrigin,sculpt.surface);addTail(bones[2],s);addExtras(bones[5],bones[3],s,headOrigin,sculpt.surface);addTufts(bones[5],s,headOrigin,sculpt.surface,bones[3]);
 addClothing(root,bones,s,skeleton,headOrigin,sculpt.surface);
 addProps(bones[5],bones[3],bones,s,headOrigin,sculpt.surface,sculpt.geometry);
 if(s.halo){root.updateMatrixWorld(true);let crest=new T.Box3().setFromObject(face).max.y;for(const child of bones[5].children)if(['AnimalEars','Hat','Tufts'].includes(child.name))crest=Math.max(crest,new T.Box3().setFromObject(child).max.y);const ring=new T.Mesh(new T.TorusGeometry(.43,.029,8,28),new T.MeshStandardMaterial({color:s.haloColor,roughness:.6}));ring.material.userData.colorSetting='haloColor';ring.name='Halo';ring.userData.role='halo';ring.position.set(0,crest-absolute[5].y+.14,.03);ring.rotation.x=Math.PI/2;bones[5].add(ring);}
 if(!s.shading){const flat=new Map();root.traverse(o=>{if(!o.isMesh)return;o.material=Array.isArray(o.material)?o.material.map(convert):convert(o.material);o.castShadow=false;});function convert(m){if(!flat.has(m))flat.set(m,new T.MeshBasicMaterial({color:m.color,map:m.map,side:m.side,transparent:m.transparent,opacity:m.opacity,alphaTest:m.alphaTest,depthWrite:m.depthWrite,depthTest:m.depthTest}));flat.get(m).userData={...m.userData};return flat.get(m);}}
 if(s.bellySeparate){const patch=new T.Mesh(new T.SphereGeometry(1,10,6),s.shading?new T.MeshStandardMaterial({color:s.bellyColor,roughness:.95}):new T.MeshBasicMaterial({color:s.bellyColor}));patch.material.userData.colorSetting='bellyColor';patch.position.set(0,-.025,.245);patch.scale.set(.20*s.body,.245,.026);bones[3].add(patch);}
 groupAccessories({root,bones},s);
 root.traverse(o=>facetMesh(o,s.filter==='lowpoly'));
 if(s.outline)addOutlines(root,s);
 const dessertBase=createDessertBase(s);const dessertBaseHeight=dessertBase?.userData.supportHeight??0;if(dessertBase){root.add(dessertBase);bones[0].position.y+=dessertBaseHeight;}
 bones[5].scale.setScalar(s.head);root.updateMatrixWorld(true);bones.forEach(b=>{b.userData.restPosition=b.position.clone();b.userData.restQuaternion=b.quaternion.clone();});return{root,bones,materials,face,dessertBase,dessertBaseHeight,rest:bones.map(b=>b.getWorldPosition(new T.Vector3())),headSurface:sculpt.surface,headOrigin,fromProvidedModel:true};}
